import React from "react";
import { Title, InputAndButton } from "./searchBar";
import "./searchBar.css";
import "bootstrap/dist/css/bootstrap.css";

class Result extends React.Component {
  constructor(props) {
    super(props);


  }

  render() {
            // 调整输入框，按钮和标题至窗口正上方
            let searchStyle = document.getElementById("search-input-button-title-div")
            .style;
          searchStyle.position = "relative";
          searchStyle.transform = "translate(-50%, 0%)";
      
          // 校准标题位置使之与输入框和按钮齐平
          let titleStyle = document.getElementById("search-title").style;
          titleStyle.position = "relative";
          titleStyle.top = "5px";
    return (
      <div className="search-input-button-title-div">
        <Title className="search-title" />
        <InputAndButton />
      </div>
    );
  }
}

class SearchResult extends React.Component {
  render() {
    return (
      <div>
        <Result {...this.props} />
      </div>
    );
  }
}

export default SearchResult;
